using BenchmarkDotNet.Running;

namespace RoselineMCP.Benchmarks;

/// <summary>
/// Entry point for the benchmark suite. Runs every <c>[Benchmark]</c>-annotated class found in
/// this assembly (<see cref="AnalyzeSolutionBenchmarks"/>, <see cref="ApplyFixesBenchmarks"/>).
/// </summary>
/// <remarks>
/// Uses an explicit class + <c>Main</c> instead of top-level statements — this project's own
/// <c>Program</c> type would otherwise collide (CS0436) with the top-level-statement
/// <c>Program</c> type generated by the referenced <c>RoselineMCP</c> executable project.
/// </remarks>
public static class BenchmarkEntryPoint
{
    /// <summary>
    /// See <c>BENCHMARKS.md</c> at the repository root for usage, e.g.
    /// <c>dotnet run -c Release --project RoselineMCP.Benchmarks -- --filter *AnalyzeSolution*</c>.
    /// </summary>
    public static void Main(string[] args) =>
        BenchmarkSwitcher.FromAssembly(typeof(BenchmarkEntryPoint).Assembly).Run(args);
}
